import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class CsvParserTest {
    @Test
    void parsesEmptyField() {
        var row = CsvParser.parse("a,,b");
        assertEquals(3, row.size());
        assertEquals("", row.get(1));
