    void rejectsNullInput() {
        assertThrows(NullPointerException.class,
            () -> CsvParser.parse(null));
    }
}

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

class Billing {
  private static final Logger log =
      LoggerFactory.getLogger(Billing.class);

  void charge(String id, long cents) {
    log.debug("charge id={} cents={}", id, cents);
    try {
      gateway.charge(id, cents);
    } catch (GatewayException e) {
      log.error("charge failed id={}", id, e);
      throw e;
    }
  }
}

record Order(String id, List<Item> items) {
    Order {
        Objects.requireNonNull(id, "id");
        items = List.copyOf(items); // NPE if null
        if (items.isEmpty())
            throw new IllegalArgumentException(
                "order " + id + " has no items");
    }
}

